// Procesar datos del paciente antes de enviar a Lambda
const inputData = $input.first().json;

// Dividir full_name en first_name y last_name
const nameParts = (inputData.full_name || '').trim().split(' ');
const firstName = nameParts[0] || '';
const lastName = nameParts.slice(1).join(' ') || '';

// Sanitizar teléfono (agregar código país si no tiene)
let phone = (inputData.phone || '').toString().trim();
if (!phone.startsWith('+')) {
  phone = '+57' + phone.replace(/\D/g, ''); // Asume Colombia +57
}

// Preparar payload para Lambda
const payload = {
  first_name: firstName,
  last_name: lastName,
  phone: phone,
  birth_date: inputData.birth_date || null,
  appointment_date: inputData.appointment_date || null,
  appointment_time: inputData.appointment_time || null,
  appointment_reason: inputData.appointment_reason || 'Consulta general',
  self_evaluation: inputData.self_evaluation || 'No',
  sessionId: inputData.sessionId || null,
  doctor_id: inputData.doctor_id || 1,
  clinic_id: inputData.clinic_id || 1
};

// Validación básica
if (!firstName) {
  throw new Error('El campo full_name es requerido');
}
if (!phone) {
  throw new Error('El campo phone es requerido');
}
if (!payload.appointment_date || !payload.appointment_time) {
  throw new Error('Los campos appointment_date y appointment_time son requeridos');
}

return { json: payload };

// Formatear respuesta exitosa
const response = $input.first().json;

return {
  json: {
    status: 'success',
    message: 'Paciente y cita creados exitosamente',
    patient_id: response.patient_id,
    appointment_id: response.appointment_id,
    chat_history_id: response.chat_history_id,
    evaluations_processed: response.evaluations_processed || 0,
    processing_time: response.processing_time_seconds || 0,
    timestamp: new Date().toISOString()
  }
};

// Formatear respuesta de error
const response = $input.first().json;

return {
  json: {
    status: 'error',
    message: 'Error al crear paciente y cita',
    error: response.error || response.details || 'Unknown error',
    error_code: response.error_code || 'UNKNOWN',
    timestamp: new Date().toISOString()
  }
};
